<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {api} from '../api';import DataPanel from './DataPanel.vue';import DocumentViewer from './DocumentViewer.vue';import StatusBadge from './StatusBadge.vue';import HelpNote from './HelpNote.vue';import NextStep from './NextStep.vue';import IssueReview from './IssueReview.vue';import {appraisalTabLabel,explainStatus,guideFor,helpText,reviewIssues,smoothScroll} from '../customerLanguage';
const props=defineProps<{file:any;module?:string}>(),emit=defineEmits(['refresh','guide']);const state=ref<any>({}),tab=ref('intake'),error=ref(''),busy=ref(false),runId=ref(''),selected=ref<number[]>([]),classifications=ref<Record<string,string>>({}),source=ref<any>(),notes=ref(''),upload=ref<File>(),replace=ref(''),fictional=ref(false),parent=ref(''),guideline=ref(''),context=ref({loan_occupancy:'unknown',transaction:'unknown',program:'',units:1});const money=()=>({value:null as string|null,confirmed:false,source:'',basis:''});const freshInput=()=>({units:[],payment:{mode:'total',total:money(),components:{payment:money(),taxes:money(),insurance:money(),association:money(),other:money()},interest_only:false,definition:''},loan:money(),value_basis:money(),appraised_value:null});const input=ref<any>(freshInput());const root=computed(()=>'/api/files/'+props.file.id+'/appraisal'),rr=computed(()=>root.value+'/runs/'+runId.value),records=computed(()=>state.value.records||[]),versions=computed(()=>props.file.documents.flatMap((d:any)=>d.versions)),version=computed(()=>versions.value.find((v:any)=>v.id===source.value?.document_version_id));function rows(k:string){return records.value.filter((r:any)=>r.kind===k)}
async function load(){const fileId=props.file.id,requestedRun=runId.value;try{const next=await api(root.value+(requestedRun?'?run_id='+requestedRun:''));if(fileId!==props.file.id||(requestedRun&&requestedRun!==runId.value))return;state.value=next;if(state.value.run)runId.value=state.value.run.id;if(!selected.value.length)selected.value=props.file.documents.filter((d:any)=>d.category!=='fixture').map((d:any)=>d.versions.at(-1)?.id).filter(Boolean)}catch(e:any){if(fileId!==props.file.id)return;error.value=e.message;if([401,403,404].includes(e.status)){state.value={};source.value=null;emit('refresh')}}}
async function act(fn:()=>Promise<any>){busy.value=true;error.value='';try{await fn();await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function command(action:string,data:any={}){if(action==='inputs'){data={...data,input:{...data.input,units:data.input.units.map(({leaseVersion,matchEvidence,...unit}:any)=>unit)}}};await act(()=>api(rr.value+'/'+action,'POST',{notes:notes.value,...data}))}
async function start(){await act(async()=>{const r=await api(root.value+'/runs','POST',{document_version_ids:selected.value,classifications:classifications.value,context:context.value,parent_id:parent.value||null,guideline_id:guideline.value?Number(guideline.value):null,idempotency_key:crypto.randomUUID()});runId.value=r.run_id})}
async function addUpload(){if(!upload.value)return;await act(async()=>{const f=new FormData;f.append('file',upload.value!);f.append('fictional_sample',fictional.value?'1':'0');await api(replace.value?'/api/documents/'+replace.value+'/versions':('/api/files/'+props.file.id+'/documents'),'POST',f);emit('refresh')})}
function addUnit(){if(input.value.units.length<4)input.value.units.push({id:String(input.value.units.length+1),inspection_occupancy:'unknown',current_occupancy:'unknown',lease_status:'unknown',rent_method:'long_term',is_adu:false,market:money(),qualifying:money()})}
function restore(){const old=JSON.parse(JSON.stringify(state.value.inputs?.data?.input||input.value)),base=freshInput();input.value={...base,...old,units:(old.units||[]).map((u:any)=>({...u,market:u.market||money(),qualifying:u.qualifying||money()})),payment:{...base.payment,...old.payment,total:old.payment?.total||money(),components:{...base.payment.components,...old.payment?.components}},loan:old.loan||money(),value_basis:old.value_basis||money()}}
function sourceRefs(f:any){const e=f.data.evidence||{};return [...(e.document_version_id?[e]:[]),...(e.image_references||[]),...(e.field_ids||[e.field_id]).filter(Boolean).map((id:number)=>state.value.facts?.find((x:any)=>x.id===id)?.data).filter(Boolean)]}
watch(()=>props.file.id,()=>{runId.value='';selected.value=[];state.value={};source.value=null;input.value=freshInput();load()});watch(runId,()=>{source.value=null;input.value=freshInput()});
const guide=computed(()=>guideFor({documents:versions.value.filter((v:any)=>v).length,runStatus:state.value.run?.status||null,hasReport:rows('report').length>0,canReview:!!props.file.permissions?.review,subject:props.module==='dscr'?'rental income':'the appraisal',failure:state.value.run?.error}));
watch(guide,(g)=>emit('guide',g),{immediate:true});
const issues=computed(()=>props.file.permissions?.review?reviewIssues(state.value.findings||[]):[]);
const detailsOpen=ref(false);
function reveal(next:string){tab.value=next;detailsOpen.value=true}
function onGuideAction(){const cta=guide.value.cta;if(cta==='upload'||cta==='start'||cta==='retry')reveal('intake');else if(cta==='export')reveal('reports');else if(cta==='review'){if(issues.value.length)document.getElementById('issue-review')?.scrollIntoView({behavior:smoothScroll(),block:'start'});else reveal('findings')}else if(cta==='none')reveal('notes')}
let timer:any;onMounted(async()=>{if(!versions.value.length)tab.value='intake';await load();timer=setInterval(load,4000)});onUnmounted(()=>clearInterval(timer));
</script>
<template><section class="card" role="tabpanel"><h2>Appraisal / Rental Income Review</h2><p class="notice">A person checks the appraisal and the rent. Missing evidence stays unknown. This is not a loan approval. If photo reading is unavailable, review the pages yourself. The tool only flags potential issues.</p><NextStep :guide="guide" @act="onGuideAction"/><IssueReview v-if="file.permissions.review&&issues.length" :issues="issues" :versions="versions"/><p v-if="busy" role="status">Saving or processing request…</p><p v-if="state.run?.error" role="alert">{{state.run.error}}</p><p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="state.audience==='restricted'">{{state.notice}}</p><template v-else-if="file.permissions.review"><details class="more-details" :open="detailsOpen" @toggle="detailsOpen=($event.target as HTMLDetailsElement).open"><summary>Appraisal details</summary><div class="actions"><button @click="load">Refresh review</button><select v-model="runId" @change="load"><option value="">Latest review</option><option v-for="r in state.runs" :value="r.id">{{explainStatus(r.status).label}}</option></select><StatusBadge :code="state.run?.status||'draft'"/><button v-if="state.run" @click="command('control',{operation:'cancel'})">Cancel processing</button><button v-if="state.run?.status==='Failed'" @click="command('control',{operation:'retry'})">Bounded retry</button></div><nav class="tabs" role="tablist"><button v-for="t in ['intake','facts','photos','rent','calculations','findings','revisions','guidelines','notes','reports']" role="tab" :aria-selected="tab===t" @click="tab=t">{{appraisalTabLabel[t]||t}}</button></nav><label>Review reason / source notes (required for changes)<textarea v-model="notes" maxlength="4000"/></label>
<div class="review-body" :class="{'has-source':source}"><div><div v-if="tab==='intake'"><form class="form-stack" @submit.prevent="addUpload"><label>Private PDF/JPEG/PNG<input type="file" accept=".pdf,.png,.jpg,.jpeg" required @change="upload=($event.target as HTMLInputElement).files?.[0]"/></label><select v-model="replace"><option value="">New original</option><option v-for="d in file.documents.filter((d:any)=>d.category!=='fixture')" :value="d.id">New immutable version of {{d.title}}</option></select><label v-if="file.is_demo"><input type="checkbox" v-model="fictional"/>This upload is fictional</label><button :disabled="busy">Preserve original in quarantine</button></form><form class="form-stack spaced" @submit.prevent="start"><label v-for="v in versions" class="check"><input type="checkbox" :value="v.id" v-model="selected"/>Version {{v.id}} · {{v.original_name}}<select v-model="classifications[v.id]"><option v-for="c in ['uncertain','appraisal','sales_comparison','rental_schedule','operating_income','addendum','photo','sketch','map','contract','contract_amendment','lease','lease_amendment','rent_roll','rent_payment','repair_completion','revised_appraisal']">{{c}}</option></select></label><label>Loan occupancy<select v-model="context.loan_occupancy"><option v-for="x in ['primary','second_home','investment','unknown']">{{x}}</option></select></label><label>Transaction<select v-model="context.transaction"><option v-for="x in ['purchase','rate_term','cash_out','unknown']">{{x}}</option></select></label><label>Units (1–4)<input v-model.number="context.units" type="number" min="1" max="4"/></label><label>Program / investor (user entry)<input v-model="context.program"/></label><label>Revision of review<select v-model="parent"><option value="">Initial review</option><option v-for="(r,i) in state.runs" :value="r.id">Earlier review {{Number(i)+1}} · {{explainStatus(r.status).label}}</option></select></label><label>Frozen guideline version<select v-model="guideline"><option value="">Public draft baseline</option><option v-for="g in state.guidelines" :value="g.id">{{g.status}} · {{g.id}}</option></select></label><button class="primary" :disabled="busy||!selected.length">Start real appraisal processing</button></form><h3>Processing coverage and limitations</h3><p v-if="state.run">Committed source extractions {{rows('document_completed').length}} / {{state.run.inputs?.length||0}} · rendered pages {{rows('page').length}}. Queued continuations preserve progress; extraction is not reviewer confirmation.</p><DataPanel :show-evidence="true" :data="rows('document')"/><DataPanel :show-evidence="true" :data="rows('document_batch')"/><p v-if="!state.run">Select preserved original versions to start. No uploaded file is replaced by sample analysis.</p></div>
<div v-else-if="tab==='facts'"><p v-if="!state.facts?.length">No extracted facts yet. Check processing progress and missing/unreadable evidence; enter only verified review inputs.</p><article v-for="f in state.facts" class="note-card"><strong>{{f.data.key}} · {{f.data.unit||'Property'}} · {{f.data.status}}</strong><DataPanel :show-evidence="true" :data="f.data"/><button @click="source=f.data">Source page {{f.data.page}}</button><input v-model="f.confirmedValue" :placeholder="f.data.normalized||'Unknown'"/><button @click="command('confirm',{field_id:f.id,value:f.confirmedValue??f.data.normalized})">Confirm with reason</button><DataPanel :show-evidence="true" v-if="f.confirmation" :data="f.confirmation"/><div v-if="f.confirmation&&state.run?.checklist?.status==='approved'"><select v-model="f.rule"><option v-for="rule in state.run.checklist.rules" :value="rule.id">{{rule.section}} · {{rule.id}}</option></select><label><input type="checkbox" v-model="f.applicable"/>I verified this specific rule applies to this evidence</label><button :disabled="!f.rule||!f.applicable" @click="command('baseline_observation',{field_id:f.id,rule_id:f.rule,applicability_confirmed:f.applicable})">Record human-verified baseline observation</button></div></article></div>
<div v-else-if="tab==='photos'" class="module-grid"><article v-for="p in rows('image')" class="card"><img :src="rr+'/artifacts/'+p.id" alt="Authenticated derived source photograph; observation is unverified" style="max-width:100%;max-height:340px"/><p>Version {{p.data.document_version_id}} · Page {{p.data.page}} · duplicate hash evidence retained</p><button @click="source=p.data">Open original page</button></article><article v-for="p in rows('photo_observation')" class="card"><img v-if="rows('page').find((x:any)=>x.data.document_version_id===p.data.document_version_id&&x.data.number===p.data.page)" :src="rr+'/artifacts/'+rows('page').find((x:any)=>x.data.document_version_id===p.data.document_version_id&&x.data.number===p.data.page).id" alt="Actual authenticated rendered page associated with unverified observation" style="max-width:100%;max-height:340px"/><DataPanel :show-evidence="true" :data="p.data"/><button @click="source=p.data">Observation beside source</button></article><p v-if="!rows('image').length">No extracted photos. Rendered-page vision may still inspect scans; unavailable vision remains explicitly incomplete.</p></div>
<div v-else-if="tab==='rent'"><HelpNote :text="helpText.dscr"/><button @click="addUnit">Add supported unit</button><button @click="restore">Restore latest confirmed inputs</button><article v-for="u in input.units" class="card spaced"><h3>Unit {{u.id}}</h3><label>Unit identity<input v-model="u.id"/></label><label v-for="key in ['inspection_occupancy','current_occupancy']">{{key}}<select v-model="u[key]"><option v-for="v in ['unknown','occupied','vacant']">{{v}}</option></select></label><label>Current lease status<select v-model="u.lease_status"><option v-for="v in ['unknown','executed','expired_month_to_month','vacant','short_term']">{{v}}</option></select></label><label>Rent method<select v-model="u.rent_method"><option v-for="v in ['unknown','long_term','short_term']">{{v}}</option></select></label><label><input type="checkbox" v-model="u.is_adu"/>ADU — scenario only, not automatically eligible</label><div v-for="k in ['market','qualifying']" class="form-grid"><h4>{{k}} rent</h4><label>USD (blank unknown,0 distinct)<input v-model="u[k].value" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"/></label><label>Source document/page or user-entry evidence<input v-model="u[k].source"/></label><label>Explicit basis<input v-model="u[k].basis"/></label><label><input v-model="u[k].confirmed" type="checkbox"/>Reviewer confirmed</label></div><label>Lease version<select v-model="u.leaseVersion"><option v-for="v in versions" :value="v.id">{{v.original_name}} · {{v.id}}</option></select></label><label>Address/unit matching evidence<input v-model="u.matchEvidence"/></label><button @click="command('unit_match',{document_version_id:Number(u.leaseVersion),unit:u.id,address_evidence:u.matchEvidence,status:'confirmed'})">Confirm evidence-based lease match</button></article><button class="primary" @click="command('inputs',{input})">Confirm inputs and create new calculation</button><h3>Extracted lease candidates — never automatically confirmed</h3><DataPanel :show-evidence="true" :data="rows('lease_candidate')"/><DataPanel :show-evidence="true" :data="rows('unit_match')"/><h3>Source rents, evidence, selected basis and guideline version</h3><DataPanel :show-evidence="true" :data="rows('rent_comparison')"/><DataPanel :show-evidence="true" :data="rows('rental_scope')"/><h3>Outstanding unit-specific evidence requests</h3><DataPanel :show-evidence="true" :data="(state.findings||[]).filter((f:any)=>f.data.evidence.unit)"/></div>
<div v-else-if="tab==='calculations'"><HelpNote :text="helpText.dscr"/><label>Payment input mode<select v-model="input.payment.mode"><option>total</option><option>components</option></select></label><label><input type="checkbox" v-model="input.payment.interest_only"/>Interest-only scenario</label><label>Reviewer-confirmed payment definition<input v-model="input.payment.definition"/></label><div v-for="[key,m] in Object.entries(input.payment.mode==='total'?{total:input.payment.total}:input.payment.components)" class="form-grid"><h4>{{key}}</h4><label>Monthly USD<input v-model="(m as any).value" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"/></label><label>Source<input v-model="(m as any).source"/></label><label><input type="checkbox" v-model="(m as any).confirmed"/>Confirmed</label></div><div v-for="key in ['loan','value_basis']" class="form-grid"><h4>{{key}}</h4><input v-model="input[key].value" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"/><input v-model="input[key].source" placeholder="Source"/><input v-model="input[key].basis" placeholder="Selected basis, not universal lower-of"/><label><input type="checkbox" v-model="input[key].confirmed"/>Confirmed</label></div><label>Appraised value separately reported<input v-model="input.appraised_value"/></label><button class="primary" @click="command('inputs',{input})">Confirm and recalculate immutable snapshot</button><DataPanel :show-evidence="true" :data="state.calculation?.data||{notice:'No confirmed inputs yet'}"/></div>
<div v-else-if="tab==='findings'"><article v-for="f in state.findings" class="note-card"><strong>{{f.status}} · {{f.data.category}}</strong><DataPanel :show-evidence="true" :data="f.data"/><button v-for="ref in sourceRefs(f)" @click="source=ref">Source V{{ref.document_version_id}} · Page {{ref.page||1}}</button><select v-model="f.next"><option v-for="s in ['reviewed','resolved','needs_follow_up','reopened','dismissed']">{{s}}</option></select><button @click="command('finding',{finding_id:f.id,status:f.next||'reviewed'})">Append disposition with reason</button></article></div>
<div v-else-if="tab==='revisions'"><p>Proposed differences only; prior confirmed inputs/reports/findings unchanged until explicit review.</p><DataPanel :show-evidence="true" :data="rows('revision')"/></div>
<div v-else-if="tab==='guidelines'"><p>Public sourced draft for Madison/designated reviewer. Developer drafts are never production approval.</p><DataPanel :show-evidence="true" :data="state.baseline"/><button @click="act(()=>api(root+'/guidelines','POST',{status:'draft',notes}))">Create draft baseline version</button><article v-for="g in state.guidelines" class="card"><DataPanel :show-evidence="true" :data="g"/><button @click="act(()=>api(root+'/guidelines','POST',{status:'approved',previous_id:g.id,notes}))">Designated client reviewer approval</button><button @click="act(()=>api(root+'/guidelines','POST',{status:'retired',previous_id:g.id,notes}))">Retire in new version</button></article></div>
<div v-else-if="tab==='notes'"><button @click="command('note')">Append internal reviewer note</button><DataPanel :show-evidence="true" :data="rows('note')"/><DataPanel :show-evidence="true" :data="rows('confirmation')"/></div>
<div v-else-if="tab==='reports'"><p>Open findings do not block downloads. Every issue and provisional calculation stays visible.</p><button class="primary" @click="command('report')">Export report</button><article v-for="r in rows('report')" class="note-card">Report {{r.data.report_version}} · {{r.data.hash}}<a v-for="format in ['pdf','xlsx']" class="button" :href="rr+'/reports/'+r.id+'/'+format">Download {{format}}</a></article></div>
</div><aside v-if="source" class="card spaced"><button @click="source=null">Close source</button><p>Document {{source.document_version_id}} · Page {{source.page||source.number||1}}</p><DocumentViewer v-if="version" :version="version" :page="source.page||source.number||1" :region="source.region_verified&&source.region?{x:source.region[0],y:source.region[1],width:source.region[2],height:source.region[3],normalized:true}:undefined"/><p v-else>Original unavailable for this role/version.</p></aside></div></details></template></section></template>

<style scoped>.review-body.has-source{display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,1fr);gap:1rem;align-items:start}.review-body aside{position:sticky;top:1rem;min-width:0}.review-body>div{min-width:0}@media(max-width:900px){.review-body.has-source{display:block}.review-body aside{position:static}}</style>
